/// <summary>
/// Returns the description and NDX ProductNames for current item in provided language
/// </summary>
/// <param name = "_languageId">LanguageId</param>
/// <returns>ItemFreeTxt</returns>
public ItemFreeTxt avaProductNames(LanguageId _languageId)
{
    #xppTexts
    ItemFreeTxt avaItemFreeTxt;
    EcoResProductTranslation avaProductTranslation = EcoResProductTranslation::findByProductLanguage(this.Product, _languageId);

    avaItemFreeTxt = this.itemDescriptionOrName(_languageId);

    if(avaProductTranslation.NDXProductName1 != '')
    {
        avaItemFreeTxt += #newLine + avaProductTranslation.NDXProductName1;
    }
    if(avaProductTranslation.NDXProductName2 != '')
    {
        avaItemFreeTxt += #newLine + avaProductTranslation.NDXProductName2;
    }

    return avaItemFreeTxt;
}

/// <summary>
/// Returns the NDX ProductNames for current item in provided language
/// </summary>
/// <param name = "_languageId">LanguageId</param>
/// <returns>ItemFreeTxt</returns>
public ItemFreeTxt avaNDXProductName(LanguageId _languageId)
{
    #xppTexts
    EcoResProductTranslation avaProductTranslation = EcoResProductTranslation::findByProductLanguage(this.Product, _languageId);
    ItemFreeTxt avaItemFreeText;

    if(avaProductTranslation)
    {
        avaItemFreeText = avaProductTranslation.NDXProductName1 + #newLine + avaProductTranslation.NDXProductName2;
    }

    return avaItemFreeText;
}

/// <summary>
/// gets the InventDimCombination record for a provided ItemId and ColorName
/// </summary>
/// <param name = "_itemId">ItemId</param>
/// <param name = "_colorName">EcoResColorName</param>
/// <returns>InventDimCombination</returns>
public static InventDimCombination avaGetColorInventDimCombination(ItemId _itemId, EcoResColorName _colorName)
{
    InventDimCombination                avaInventDimCombination;
    EcoResDistinctProductVariant        avaDistinctVariant;
    EcoResProductVariantDimensionValue  avaVariantDimensionValue;
    EcoResProductVariantColor           avaVariantColor;

    select firstonly * from avaInventDimCombination
        join avaDistinctVariant
        join avaVariantDimensionValue
        join avaVariantColor
        where avaInventDimCombination.DistinctProductVariant    == avaDistinctVariant.RecId
            && avaDistinctVariant.RecId                         == avaVariantDimensionValue.DistinctProductVariant
            && avaVariantDimensionValue.RecId                   == avaVariantColor.RecId
            && avaDistinctVariant.ProductMaster                 == InventTable::find(_itemId).Product
            && avaVariantColor.Color                            == EcoResColor::findByName(_colorName).RecId;

    return avaInventDimCombination;
}

/// <summary>
/// KCS_GetHK2perQty() from AX2009
/// </summary>
/// <param name = "_qty">Qty</param>
    /// <param name = "_inventDimId">InventDimId</param>
    /// <param name = "_transDate">TransDate</param>
    /// <param name = "_HK2Factor">boolean</param>
    /// <param name = "_mgkFactor">boolean</param>
    /// <returns>Price</returns>
    Price AVAGetHK2perQty(  Qty         _qty         = 1,
                            InventDimId _inventDimId = inventDim::inventDimIdBlank(),
                            TransDate   _transDate   = DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone()),
                            boolean     _HK2Factor   = true,
                            boolean     _mgkFactor   = true)


    {
        InventDim           inventDim       = inventDim::find(_inventDimId);

        //KCS_HK2FactorGroup  hK2FactorGroup  = KCS_HK2FactorGroup::findDate(this.KCS_HK2GroupId, DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone()));
        KCS_HK2Vendor       hk2Vendor       = this.KCS_HK2Vendor ? this.KCS_HK2Vendor : this.PrimaryVendorId;

        PriceDiscParameters priceDiscParameters;
        PriceDisc           priceDisc;
        PriceDiscTable      avaPriceDiscTable;

        //CurrencyCode        currencyCodeVendor;

        TransDate           transDate       = _transDate;
        Qty                 qty             = _qty;
        //Qty                 qty2;
        PriceGroupId        priceGroupId    = '';

        //ExchRate            exchRate;
        KCS_PRMPriceSales   priceSales;

        if (InventItemSetupSupplyType::getDefaultOrderType(this.ItemId, this.DataAreaId) ==  ReqPOType::Purch && hk2Vendor == '')
        {
            return 0;
        }

        if (!NDXPrivilegeManagement::hasSecuritykeyAccess(privilegeStr(NDXHK2View)))
        {
            return 0;
        }

        priceDiscParameters = PriceDiscParameters::construct();

        priceDiscParameters.parmModuleType(ModuleInventPurchSales::Purch);
        priceDiscParameters.parmItemId(this.ItemId);
        priceDiscParameters.parmInventDim(inventDim);
        PriceDiscParameters.parmUnitID(this.purchUnitId());
        PriceDiscParameters.parmPriceDiscDate(transDate);
        PriceDiscParameters.parmQty(qty);
        PriceDiscParameters.parmAccountNum(hk2Vendor);
        priceDiscParameters.parmCurrencyCode();

        priceDisc = PriceDisc::newFromPriceDiscParameters(priceDiscParameters);
        priceDisc.findPrice(priceGroupId);

        avaPriceDiscTable = priceDisc.priceTable();
        //priceSales = avaPriceDiscTable.AVAchargeAmount();
        //priceSales = qty != 0 ?  avaPriceDiscTable.AVAchargeAmount() * qty :avaPriceDiscTable.AVAchargeAmount();
        InventTableModule       purchInventTableModule = this.inventTableModulePurch();

        priceSales = avaPriceDiscTable.AVAchargeAmount();
        priceSales = priceSales * purchInventTableModule.priceUnit;
        if(avaPriceDiscTable.PriceUnit)
        {
            priceSales = priceSales / avaPriceDiscTable.PriceUnit;
        }
        else if(purchInventTableModule.priceUnit)
        {
            priceSales = priceSales / purchInventTableModule.priceUnit;
        }
        priceSales = priceSales * qty;


        if (_HK2Factor)
        {
            priceSales = priceSales * this.avaGetHK2Factor(transDate);
        }
        if (_mgkFactor)
        {
            priceSales = priceSales * this.avaGetMGKFactor();
        }

       /* Price               price           = this.KCS_GetHK1perQty(qty? qty :1 , inventDimId, transDate, checkPrice, fallback);
        KCS_HK2FactorGroup  hK2FactorGroup  = KCS_HK2FactorGroup::findDate(this.KCS_HK2GroupId,
                                                                       transDate) ;

        KCS_HK2Factor       hK2Factor       = hk2FactorGroup ? hK2FactorGroup.HK2Factor : 1;

        return Price * hK2Factor;    
     //   return this.inventTableModulePurch().NDX_showHK2PriceDisc  ()      */


        return priceSales;

    }

/// <summary>
/// returns HK2 factor from group for certain date
/// </summary>
/// <param name = "_transDate">TransDate, default system date</param>
/// <returns>KCS_HK2Factor</returns>
KCS_HK2Factor avaGetHK2Factor(TransDate _transDate = DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone()))
{
    KCS_HK2FactorGroup  hk2FactorGroup  = KCS_HK2FactorGroup::findDate(this.KCS_HK2GroupId, _transDate);
    KCS_HK2Factor       hk2Factor       = hk2FactorGroup ? hk2FactorGroup.HK2Factor : 1;

    return hk2Factor;
}

/// <summary>
/// returns MGK factor from Group
/// </summary>
/// <returns>AVAMGKFactor</returns>
AVAMGKFactor avaGetMGKFactor()
{
    //AVAMGKFactors avaMGKFactors = AVAMGKFactors::findGroupId(this.inventTableModuleInvent().AVAMGKGroup);
    AVAMGKFactors avaMGKFactors = AVAMGKFactors::findByRecId(this.inventTableModuleInvent().NDXMGKGroupRefRecId);
    AVAMGKFactor avaMGKFactor = avaMGKFactors ? avaMGKFactors.MGKFactor : 1;

    return avaMGKFactor;
}

