/// <summary>
///    AVA <c>avaGetPriceSurchargeCode</c> method.
/// </summary>
/// <returns>
///    <c>AVAPriceSurchargeCode</c> as return value
/// </returns>
public AVAPriceSurchargeCode avaGetPriceSurchargeCode()
{
    AVAPriceSurchargeCode   retVal;

    if(this.AVAPriceSurchargeCode)
    {
        retVal = this.AVAPriceSurchargeCode;
    }
    else if(this.KCS_GoodsId)
    {
        retVal = KCS_GoodsGroup::find(this.KCS_GoodsId).AVAPriceSurchargeCode;
    }

    return retVal;
}

