/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "_costingVersion">_costingVersion</param>
/// <param name = "_priceDate">_priceDate</param>
/// <param name = "_inventDim">_inventDim</param>
/// <param name = "_qty">_qty</param>
/// <param name = "_unit">_unit</param>
/// <param name = "_accountNum">_accountNum</param>
/// <returns>conrainer</returns>
public container AVAPurchPriceAgreement(CostingVersion      _costingVersion,
                                        PriceDate           _priceDate,
                                        InventDim           _inventDim,
                                        Qty                 _qty,
                                        UnitOfMeasureSymbol _unit,
                                        VendAccount         _accountNum = this.primaryVendorId(_inventDim.InventDimId, _inventDim))

{
 //   container       result;
 //   PriceDiscTable          priceDiscTable;

   /* select firstonly priceDiscTable
        order by FromDate
        where priceDiscTable.ItemCode == PriceDiscProductCodeType::Table
           && priceDiscTable.ItemRelation == this.ItemId
           && priceDiscTable.AccountCode == PriceDiscPartyCodeType::All
           && priceDiscTable.AccountRelation == ''
           && priceDiscTable.AVAGraduatedPrice == NoYes::Yes
           && priceDiscTable.QuantityAmountFrom <= _qty
           && (priceDiscTable.QuantityAmountTo   >= _qty || priceDiscTable.QuantityAmountTo == 0)
           && priceDiscTable.UnitId            == _unit
          // && priceDiscTable.InventDimId         == _inventDim.inventDimId
           && ((priceDiscTable.FromDate          >= _costingVersion.DefaultDate && (priceDiscTable.FromDate <= _costingVersion.KCS_ToDate || _costingVersion.KCS_ToDate == dateNull()))
           ||  (priceDiscTable.ToDate            >= _costingVersion.DefaultDate && (priceDiscTable.ToDate   <= _costingVersion.KCS_ToDate || _costingVersion.KCS_ToDate == dateNull())));

           result = [priceDiscTable.price(), 
                priceDiscTable.priceUnit(), 
                priceDiscTable.markup(), 
                priceDiscTable.FromDate, 
                priceDiscTable.ToDate, 
                0,0];*/
    VendAccount         accountNum         = _accountNum;
    CurrencyCode        currencyCode       = VendTable::find(accountNum).Currency;
    boolean             includeLineDisc    = true;

    InventPurchPriceAgreementCalculationParameters parameters = InventPurchPriceAgreementCalculationParameters::newFromInventTable(this);

    parameters.priceDate = _priceDate;
    parameters.inventDim = _inventDim;
    parameters.qty = _qty;
    parameters.unit = _unit;
    parameters.accountNum = accountNum;
    parameters.currencyCode = currencyCode;
    parameters.includeLineDisc = includeLineDisc;

    InventPurchPriceAgreementCalculation  inventPurchPriceAgreementCalculation = InventPurchPriceAgreementCalculation::newFromParameters(parameters);
    inventPurchPriceAgreementCalculation.parmAVAGraduatedPrice(true);
    inventPurchPriceAgreementCalculation.parmCostingVersion(_costingVersion);

    InventPurchPriceAgreementCalculationResult result = inventPurchPriceAgreementCalculation.purchPriceAgreement();


    return [result.costPrice,
            result.costPriceUnit,
            result.costMarkup,
            result.priceDiscFromDate,
            result.priceDiscToDate,
            result.costPriceSecCur,
            result.costMarkupSecCur];
   // return result;

}

