/// <summary>
///     AVA <c>avaBOMIdStandard</c> method.
/// </summary>
/// <returns>
///     <c>BOMId</c> as type
/// </returns>
[SysClientCacheDataMethodAttribute(true)]
display BOMId avaBOMIdStandard()
{
    BOMId           retVal;

    InventDim       inventDimOrderSetupKey;

    if (!this.RecId)
    {
        return retVal;
    }

    inventDimOrderSetupKey.clear();

    inventDimOrderSetupKey.InventSiteId = this.inventInventSiteId();
    inventDimOrderSetupKey              = InventDim::findOrCreate(inventDimOrderSetupKey);

    retVal = this.bomId(DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone()),
                        this.inventStandardQty(inventDimOrderSetupKey.InventDimId),
                        inventDimOrderSetupKey                                                  
                        );
    return retVal;
}

