/// <summary>
///     AVA <c>avaBOMVersionActualNoOfItems</c> method.
/// </summary>
/// <returns>
///     <c>int64</c> as type
/// </returns>
[SysClientCacheDataMethodAttribute(true)]
display int64 avaBOMVersionActualNoOfItems()
{
    int64       retVal;

    BomVersion  locBomVersion;
    BOM         locBOM;

    locBomVersion = this.avaBOMVersionActual();

    if(locBomVersion)
    {
        select count(RecId) 
        from    locBOM
        where   locBOM.BOMId    == locBomVersion.BOMId
            //&&  locBOM.BOMType  == BOMType::Item
            &&  locBOM.BOMQty   > 0;
    }

    retVal = locBOM.RecId;

    return retVal;
}

