/// <summary>
///     AVA <c>avaRouteVersionActualNoOfItems</c> method.
/// </summary>
/// <returns>
///     <c>int64</c> as type
/// </returns>
[SysClientCacheDataMethodAttribute(true)]
display int64 avaRouteVersionActualNoOfItems()
{
    int64         retVal;

    RouteVersion  locRouteVersion;
    Route         locRoute;

    locRouteVersion = this.avaRouteVersionActual();

    if(locRouteVersion)
    {
        select count(RecId)
        from    locRoute
        //where   locRoute.RouteId == locRouteVersion.RouteId;
        where locRoute.RouteId == locRouteVersion.RouteId
            && locRoute.OprPriority == RouteOprPriority::Primary;
    }

    retVal = locRoute.RecId;

    return retVal;
}

