/// <summary>
///     AVA <c>avaGetHK2Date</c> method.
/// </summary>
/// <param name="_inventDimId">
///     <c>InventDimId</c> as type
/// </param>
/// <param name="_transDate">
///     <c>TransDate</c> as type
/// </param>
/// <returns>
///     <c>TransDate</c> as return value
/// </returns>
TransDate avaGetHK2Date(InventDimId _inventDimId = inventDim::inventDimIdBlank(),
                        TransDate   _transDate   = DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone()))
{
    TransDate           retVal;

    InventItemPrice     locInventItemPrice;
    InventParameters    locInventParameters;
    CostingVersionId    locCostingVersionId;

    locInventParameters = InventParameters::find();

    // Keine Datumermittlung für Handelsware
    /*
    if (    this.KCS_HK2Vendor 
        &&  (       this.isBOMAllowed()                     // 2009: this.ItemType != ItemType::BOM  
                                                            // ||  this.StopExplode 
                ||  this.stopExplodeBOMPrice()      )   )
    */
    if(InventItemSetupSupplyType::getDefaultOrderType(this.ItemId, curExt()) == ReqPOType::Purch)
    {
        retVal = DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone());
    }
    else
    {
        locCostingVersionId = this.KCS_currentVersionId(_transDate);
        locInventItemPrice  = InventItemPrice::KCS_findCostingVersion(  this.ItemId,
                                                                        locCostingVersionId,
                                                                        _transDate,
                                                                        this.KCS_defaultCostingPriceType(),
                                                                        _inventDimId                        );
        retVal = locInventItemPrice.ActivationDate;
    }
    return retVal;
}

